<?php require_once '../config/auth.php';requireLogin();require_once '../config/database.php';if($_SERVER['REQUEST_METHOD']==='POST'){$nome=trim($_POST['nome']);$email=trim($_POST['email']);$senha=password_hash($_POST['senha'],PASSWORD_DEFAULT);$tipo=$_POST['tipo'];$s=$conn->prepare("INSERT INTO utilizadores(nome,email,senha,tipo) VALUES(?,?,?,?)");$s->bind_param('ssss',$nome,$email,$senha,$tipo);$s->execute();header('Location: index.php');exit;}?><!doctype html><html lang="pt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Novo utilizador</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="container"><div class="card"><h1>Novo utilizador</h1><form method="post"><input name="nome" placeholder="Nome" required><input type="email" name="email" placeholder="Email" required><input type="password" name="senha" placeholder="Senha" required minlength="6"><select name="tipo"><option value="leitor">Leitor</option><option value="funcionario">Funcionário</option><option value="admin">Administrador</option></select><button>Guardar</button></form></div></div></body></html>
